#!/usr/bin/env python3
"""Extracts the ShellFileReadResult model and its line counter from ShellClient.kt.

ShellToolJson.kt and BoundedFileReadJson.kt compile VERBATIM from the app tree; only these two
declarations live in the transport-heavy ShellClient.kt, so the stand copies them verbatim into
a generated file (no visibility changes are needed).

Usage: python3 extract_shell_models.py <ShellClient.kt> <out.kt>
"""
import sys

MODELS = [
    "data class ShellFileReadResult(",
]
FUNCTIONS = [
    "internal fun shellFileLineCount(content: String): Int =",
]

HEADER = """\
// GENERATED by extract_shell_models.py from ShellClient.kt -- do not edit.
//
// ShellFileReadResult and shellFileLineCount are copied verbatim from the transport-heavy
// ShellClient.kt so the shell-tools golden stand can compile the real BoundedFileReadJson.
package com.newoether.agora.util

"""


def extract_class(lines, marker):
    start = None
    for i, line in enumerate(lines):
        if line.startswith(marker):
            start = i
            break
    if start is None:
        raise SystemExit(f"error: {marker} not found")
    end = None
    for i in range(start, len(lines)):
        if lines[i].strip() == ")":
            end = i
            break
    if end is None:
        raise SystemExit(f"error: closing paren of {marker} not found")
    return lines[start : end + 1]


def extract_function(lines, marker):
    for i, line in enumerate(lines):
        if line.startswith(marker):
            # Expression body on one line (`= if ... else ...` spans two lines here).
            if lines[i].rstrip().endswith("="):
                return lines[i : i + 2]
            return [line]
    raise SystemExit(f"error: {marker} not found")


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: extract_shell_models.py <ShellClient.kt> <out.kt>", file=sys.stderr)
        return 2
    source_path, out_path = sys.argv[1], sys.argv[2]
    lines = open(source_path, encoding="utf-8").read().split("\n")

    blocks = []
    for marker in MODELS:
        blocks.append("\n".join(extract_class(lines, marker)))
    for marker in FUNCTIONS:
        blocks.append("\n".join(extract_function(lines, marker)))

    text = "\n\n".join(blocks)
    for name in ("ShellFileReadResult", "shellFileLineCount"):
        if name not in text:
            raise SystemExit(f"error: {name} missing from the extracted region")

    with open(out_path, "w", encoding="utf-8") as handle:
        handle.write(HEADER + text + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
